-- ---------------------------------------------------------------------------
-- Load ACT demo patient data (500 synthetic patients) into Snowflake.
--
-- Parquet files are generated by demo_patients/generate_act_demo_patients.py
-- and shipped in crcdata_DEMO_PATIENTS.zip (unzipped to ./demo_patients by the
-- db_demodata_load_data ant target). All facts use concept codes present in
-- the ACT ontology CONCEPT_DIMENSION, so webclient queries return results.
--
-- When running manually (snowsql), replace ${basedir} with the absolute path
-- of the Crcdata directory.
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FILE FORMAT DEMO_PARQUET_FORMAT
    TYPE = PARQUET
    COMPRESSION = SNAPPY;
CREATE OR REPLACE STAGE DEMO_PATIENT_STAGE FILE_FORMAT = DEMO_PARQUET_FORMAT;
PUT file://${basedir}/act/scripts/snowflake/demo_patients/*.snappy.parquet @DEMO_PATIENT_STAGE PARALLEL=4 AUTO_COMPRESS=FALSE OVERWRITE=TRUE;
DELETE FROM OBSERVATION_FACT WHERE SOURCESYSTEM_CD = 'ACT_DEMO';
DELETE FROM VISIT_DIMENSION WHERE SOURCESYSTEM_CD = 'ACT_DEMO';
DELETE FROM ENCOUNTER_MAPPING WHERE SOURCESYSTEM_CD = 'ACT_DEMO';
DELETE FROM PATIENT_DIMENSION WHERE SOURCESYSTEM_CD = 'ACT_DEMO';
DELETE FROM PATIENT_MAPPING WHERE SOURCESYSTEM_CD = 'ACT_DEMO';
DELETE FROM PROVIDER_DIMENSION WHERE SOURCESYSTEM_CD = 'ACT_DEMO';
COPY INTO PATIENT_DIMENSION FROM @DEMO_PATIENT_STAGE/PATIENT_DIMENSION MATCH_BY_COLUMN_NAME = CASE_INSENSITIVE FILE_FORMAT = DEMO_PARQUET_FORMAT;
COPY INTO PATIENT_MAPPING FROM @DEMO_PATIENT_STAGE/PATIENT_MAPPING MATCH_BY_COLUMN_NAME = CASE_INSENSITIVE FILE_FORMAT = DEMO_PARQUET_FORMAT;
COPY INTO VISIT_DIMENSION FROM @DEMO_PATIENT_STAGE/VISIT_DIMENSION MATCH_BY_COLUMN_NAME = CASE_INSENSITIVE FILE_FORMAT = DEMO_PARQUET_FORMAT;
COPY INTO ENCOUNTER_MAPPING FROM @DEMO_PATIENT_STAGE/ENCOUNTER_MAPPING MATCH_BY_COLUMN_NAME = CASE_INSENSITIVE FILE_FORMAT = DEMO_PARQUET_FORMAT;
COPY INTO PROVIDER_DIMENSION FROM @DEMO_PATIENT_STAGE/PROVIDER_DIMENSION MATCH_BY_COLUMN_NAME = CASE_INSENSITIVE FILE_FORMAT = DEMO_PARQUET_FORMAT;
COPY INTO OBSERVATION_FACT FROM @DEMO_PATIENT_STAGE/OBSERVATION_FACT MATCH_BY_COLUMN_NAME = CASE_INSENSITIVE FILE_FORMAT = DEMO_PARQUET_FORMAT;
